"use client";

import { Reorder } from "motion/react";
import { type FormEvent, useEffect, useId, useLayoutEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { SparklesIcon } from "../parts/icons";
import { StopIcon } from "./shared/icons";
import { ALTERNATES, DRAFT_PLAN, DRAFTER, PARALLEL, type PlanTask, START_GOAL } from "./task-breakdown/data";
import { ShipLine } from "./task-breakdown/ship-line";
import { TaskRow } from "./task-breakdown/task-row";

type Phase = "idle" | "thinking" | "streaming" | "done";

const TICK_MS = 90;
const WORDS_PER_TICK = 2;
const wordCount = (task: PlanTask) => task.title.split(" ").length;

/**
 * Turns one goal into a plan. The plan streams in a row at a time, each row's
 * details appear once its title is whole, and the ship line shows live whether
 * the deadline holds. Rows can be reordered, renamed or drafted again, and the
 * plan can be sent to the tracker one issue at a time.
 */
export function TaskBreakdown({ className }: { className?: string }) {
  const [goal, setGoal] = useState(START_GOAL);
  const [phase, setPhase] = useState<Phase>("idle");
  const [tasks, setTasks] = useState<PlanTask[]>([]);
  const [words, setWords] = useState<Map<string, number>>(() => new Map());
  const [sent, setSent] = useState<Map<string, string>>(() => new Map());
  const refocus = useRef<string | null>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const titleId = useId();
  const goalId = useId();

  // Thinking lasts a moment, then the stream starts.
  useEffect(() => {
    if (phase !== "thinking") return;
    const timer = window.setTimeout(() => setPhase("streaming"), 700);
    return () => window.clearTimeout(timer);
  }, [phase]);

  // Each tick adds a few words to the first row that is not whole yet.
  useEffect(() => {
    if (phase !== "streaming") return;
    const next = tasks.find((task) => (words.get(task.id) ?? 0) < wordCount(task));
    const timer = window.setTimeout(() => {
      if (!next) setPhase("done");
      else setWords((current) => new Map(current).set(next.id, (current.get(next.id) ?? 0) + WORDS_PER_TICK));
    }, TICK_MS);
    return () => window.clearTimeout(timer);
  }, [phase, tasks, words]);

  // Issues are created one after another, so each row reports its own progress.
  useEffect(() => {
    const pending = tasks.find((task) => sent.get(task.id) === "queued" || sent.get(task.id) === "sending");
    if (!pending) return;
    const timer = window.setTimeout(() => {
      setSent((current) => {
        const state = current.get(pending.id);
        const created = [...current.values()].filter((value) => value.startsWith("FH")).length;
        return new Map(current).set(pending.id, state === "queued" ? "sending" : `FH-${301 + created}`);
      });
    }, 350);
    return () => window.clearTimeout(timer);
  }, [sent, tasks]);

  // A row moved by keyboard keeps focus on its grip.
  useLayoutEffect(() => {
    const id = refocus.current;
    refocus.current = null;
    if (id) listRef.current?.querySelector<HTMLElement>(`[data-grip="${id}"]`)?.focus();
  }, [tasks]);

  const drafting = phase === "thinking" || phase === "streaming";

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (drafting) {
      stop();
      return;
    }
    if (!goal.trim()) return;
    setTasks(DRAFT_PLAN);
    setWords(new Map());
    setSent(new Map());
    setPhase("thinking");
  };

  const stop = () => {
    // Rows that never started are dropped; a half-written title keeps what streamed.
    setTasks((current) =>
      current.flatMap((task) => {
        const shown = words.get(task.id) ?? 0;
        if (shown === 0) return [];
        return [{ ...task, title: task.title.split(" ").slice(0, shown).join(" ") }];
      }),
    );
    setPhase("done");
  };

  const move = (id: string, step: -1 | 1) => {
    const index = tasks.findIndex((task) => task.id === id);
    const target = index + step;
    if (index < 0 || target < 0 || target >= tasks.length) return;
    const next = [...tasks];
    const [task] = next.splice(index, 1);
    if (!task) return;
    next.splice(target, 0, task);
    refocus.current = id;
    setTasks(next);
  };

  const redraft = (id: string) => {
    const alternate = ALTERNATES.get(id);
    setTasks((current) =>
      current.map((task) => {
        if (task.id !== id) return task;
        // Drafting again swaps between the first wording and the second.
        const original = DRAFT_PLAN.find((item) => item.id === id);
        const useOriginal = original && alternate && task.title === alternate.title;
        return useOriginal ? original : alternate ? { ...task, ...alternate } : task;
      }),
    );
    setWords((current) => new Map(current).set(id, 0));
    setPhase("streaming");
  };

  const totalDays = tasks.reduce((sum, task) => sum + task.days, 0);
  const teamDays = Math.ceil(totalDays / PARALLEL);
  const created = [...sent.values()].filter((value) => value.startsWith("FH")).length;
  const sending = sent.size > 0 && created < tasks.length;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-2xl", className)}>
      <form onSubmit={submit} className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Plan a goal
        </h2>
        <div className="flex flex-wrap gap-2">
          <label htmlFor={goalId} className="sr-only">
            Goal
          </label>
          <Input
            id={goalId}
            value={goal}
            onChange={(event) => setGoal(event.target.value)}
            disabled={drafting}
            className="min-w-0 flex-1 basis-60"
          />
          <Button type="submit" variant={drafting ? "outline" : "default"} disabled={!drafting && !goal.trim()}>
            {drafting ? <StopIcon /> : <SparklesIcon />}
            {drafting ? "Stop" : "Break it down"}
          </Button>
        </div>
      </form>

      {phase === "idle" ? (
        <p className="px-5 py-10 text-center text-sm text-muted-foreground">Write a goal and press Enter to draft the tasks.</p>
      ) : (
        <div className="flex flex-col gap-4 px-5 py-4">
          <dl className="grid grid-cols-2 gap-3 text-sm">
            <div>
              <dt className="text-xs text-muted-foreground">Tasks</dt>
              <dd className="text-lg font-semibold tabular-nums">{tasks.length}</dd>
            </div>
            <div>
              <dt className="text-xs text-muted-foreground">Effort</dt>
              <dd className="text-lg font-semibold tabular-nums">
                {totalDays} days <span className="text-sm font-normal text-muted-foreground">across {PARALLEL} people</span>
              </dd>
            </div>
          </dl>
          <ShipLine days={drafting ? Math.ceil(tasks.filter((task) => (words.get(task.id) ?? 0) >= wordCount(task)).reduce((sum, task) => sum + task.days, 0) / PARALLEL) : teamDays} />

          {phase === "thinking" ? (
            <p className="flex items-center gap-2 text-sm text-muted-foreground motion-safe:animate-pulse" role="status">
              <SparklesIcon aria-hidden="true" className="size-4 text-chart-1" />
              Thinking through the steps
            </p>
          ) : null}

          <Reorder.Group
            ref={listRef}
            axis="y"
            values={tasks}
            onReorder={setTasks}
            aria-label="Tasks"
            aria-busy={drafting}
            className="flex flex-col gap-2"
          >
            {tasks
              .filter((task) => words.has(task.id))
              .map((task) => {
                const number = tasks.indexOf(task) + 1;
                const after = task.after ? tasks.findIndex((item) => item.id === task.after) : -1;
                return (
                  <TaskRow
                    key={task.id}
                    task={task}
                    number={number}
                    afterNumber={after >= 0 ? after + 1 : null}
                    words={words.get(task.id) ?? 0}
                    locked={drafting || sending}
                    send={sent.get(task.id)}
                    onMove={(step) => move(task.id, step)}
                    onRename={(title) => setTasks((current) => current.map((item) => (item.id === task.id ? { ...item, title } : item)))}
                    onRedraft={() => redraft(task.id)}
                  />
                );
              })}
          </Reorder.Group>

          <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-3">
            <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <SparklesIcon aria-hidden="true" className="size-3.5 text-chart-1" />
              Drafted by {DRAFTER}
            </span>
            <div className="flex items-center gap-3">
              <span className="text-xs tabular-nums text-muted-foreground" role="status">
                {sent.size > 0 ? `${created} of ${tasks.length} issues created` : ""}
              </span>
              <Button
                size="sm"
                variant="outline"
                disabled={drafting || sending || tasks.length === 0 || created === tasks.length}
                onClick={() => setSent(new Map(tasks.map((task) => [task.id, "queued"])))}
              >
                Send to tracker
              </Button>
            </div>
          </div>
        </div>
      )}
    </BlockFrame>
  );
}

