/** One task in a drafted plan. */
export interface PlanTask {
  id: string;
  title: string;
  /** The task this one waits for, by id. */
  after?: string;
  /** Effort in working days. */
  days: number;
  owner: string;
}

/** The goal the field starts with. */
export const START_GOAL = "Let patients join a waitlist for cancelled slots";

/** The plan the drafter writes for any goal. Titles mention the goal's subject where it reads naturally. */
export const DRAFT_PLAN: PlanTask[] = [
  { id: "p1", title: "Map how front desks fill a cancelled slot today", days: 2, owner: "noor" },
  { id: "p2", title: "Store a waitlist per practitioner and visit type", after: "p1", days: 4, owner: "kofi" },
  { id: "p3", title: "Let patients join the waitlist from the booking page", after: "p2", days: 5, owner: "ines" },
  { id: "p4", title: "Text the first patient in line when a slot opens", after: "p2", days: 4, owner: "lena" },
  { id: "p5", title: "Give the slot to whoever replies yes first", after: "p4", days: 3, owner: "kofi" },
  { id: "p6", title: "Pilot at Harbour Street and measure filled slots", after: "p5", days: 5, owner: "tomas" },
];

/** A second wording for each task, used when a row is drafted again. */
export const ALTERNATES = new Map<string, Omit<PlanTask, "id" | "after">>([
  ["p1", { title: "Sit with two front desks for a morning of cancellations", days: 1, owner: "noor" }],
  ["p2", { title: "Add a waitlist table keyed by clinic and visit length", days: 3, owner: "arjun" }],
  ["p3", { title: "Add a join waitlist step after a fully booked day", days: 4, owner: "ines" }],
  ["p4", { title: "Send the open slot to three patients at once", days: 3, owner: "lena" }],
  ["p5", { title: "Hold the slot for 15 minutes per patient in turn", days: 4, owner: "kofi" }],
  ["p6", { title: "Roll out to two clinics and compare no-show rates", days: 6, owner: "tomas" }],
]);

/** The name shown beside drafted plans. Invented. */
export const DRAFTER = "Fernhill Planner 2";

/** Working days from Monday, Nov 16, 2026, to the deadline on Friday, Dec 4, inclusive. */
export const DEADLINE_DAYS = 15;

/** How many people work in parallel, so the team finishes in total effort over this. */
export const PARALLEL = 2;

const START = Date.UTC(2026, 10, 16);
const SHORT = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });

/** The date of the nth working day from Nov 16, counting Nov 16 as day 1. */
export function workingDate(n: number) {
  let date = START;
  let left = Math.max(1, n) - 1;
  while (left > 0) {
    date += 86_400_000;
    const weekday = new Date(date).getUTCDay();
    if (weekday !== 0 && weekday !== 6) left -= 1;
  }
  return SHORT.format(new Date(date));
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { DEADLINE_DAYS, workingDate } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for the ship date line. */
export interface ShipLineProps {
  /** Working days the plan needs, counting from Nov 16. */
  days: number;
}

/**
 * A line from the start to the deadline with the projected ship day on it.
 * The fill turns warm and runs past the deadline mark when the plan is late,
 * and the sentence above it says so in words.
 */
export function ShipLine({ days }: ShipLineProps) {
  const reduceMotion = useReducedMotion();
  const late = days > DEADLINE_DAYS;
  const scale = Math.max(DEADLINE_DAYS, days) * 1.1;
  const gap = Math.abs(DEADLINE_DAYS - days);
  const ship = days === 0 ? "Nothing planned yet" : `Ships ${workingDate(days)}`;
  const versus =
    days === 0 ? "" : late ? `, ${gap} working ${gap === 1 ? "day" : "days"} after the deadline` : gap === 0 ? ", on the deadline" : `, ${gap} working ${gap === 1 ? "day" : "days"} to spare`;
  return (
    <div className="flex flex-col gap-2">
      <p className="text-sm" aria-live="polite">
        <span className={cn("font-medium", days > 0 && (late ? STATUS_TEXT.bad : STATUS_TEXT.good))}>{ship}</span>
        <span className="text-muted-foreground">{versus}</span>
      </p>
      <div aria-hidden="true" className="relative h-2 rounded-full">
        <span className="absolute inset-0 rounded-full bg-muted-foreground/20" />
        <motion.span
          className={cn("absolute inset-y-0 left-0 w-full origin-left rounded-full", late ? "bg-chart-5" : "bg-chart-2")}
          initial={false}
          animate={{ scaleX: days / scale }}
          transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 200, damping: 30 }}
        />
        <span
          className="left-(--left) absolute -inset-y-1.5 w-0.5 rounded-full bg-foreground"
          style={
            // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
            { "--left": `${(DEADLINE_DAYS / scale) * 100}%` } as VarStyle
          }
        />
      </div>
      <div aria-hidden="true" className="relative h-4 text-xs text-muted-foreground">
        <span className="absolute left-0">Nov 16</span>
        <span className="left-(--left) absolute -translate-x-1/2" style={
          // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
          { "--left": `${(DEADLINE_DAYS / scale) * 100}%` } as VarStyle
        }>
          Deadline {workingDate(DEADLINE_DAYS)}
        </span>
      </div>
    </div>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
