/** Props for one task row. */
export interface TaskRowProps {
  task: PlanTask;
  number: number;
  /** The number of the task this one waits for, if any, and whether that task now sits below it. */
  afterNumber: number | null;
  /** How many words of the title have streamed in. */
  words: number;
  /** True while any row is still streaming: reordering and editing wait. */
  locked: boolean;
  /** Where the task stands in the send to the tracker: "queued", "sending", or its reference such as FH-301 once created. */
  send: string | undefined;
  onMove: (step: -1 | 1) => void;
  onRename: (title: string) => void;
  onRedraft: () => void;
}

/**
 * One drafted task. Its title streams in a few words at a time and its
 * details fade in once the title is whole. A grip reorders it by drag, or by
 * up and down while focus stays on the grip. Enter on the title edits it.
 */
export function TaskRow({ task, number, afterNumber, words, locked, send, onMove, onRename, onRedraft }: TaskRowProps) {
  const reduceMotion = useReducedMotion();
  const controls = useDragControls();
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(task.title);
  const all = task.title.split(" ");
  const complete = words >= all.length;
  const owner = person(task.owner);

  const onGripKey = (event: KeyboardEvent) => {
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
    event.preventDefault();
    onMove(event.key === "ArrowUp" ? -1 : 1);
  };

  return (
    <Reorder.Item
      value={task}
      dragListener={false}
      dragControls={controls}
      transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 50 }}
      className="relative flex items-start gap-2 rounded-xl border border-border bg-card px-2 py-2.5"
    >
      <Button
        variant="ghost"
        size="icon"
        className="size-7 shrink-0 cursor-grab touch-none"
        data-grip={task.id}
        disabled={locked}
        aria-label={`Move task ${number}, ${task.title}. Use up and down.`}
        onPointerDown={(event) => controls.start(event)}
        onKeyDown={onGripKey}
      >
        <GripVerticalIcon />
      </Button>
      <span className="w-5 shrink-0 pt-1 text-xs font-medium tabular-nums text-muted-foreground">{number}</span>
      <div className="flex min-w-0 flex-1 flex-col gap-1.5">
        {editing ? (
          <Input
            autoFocus
            aria-label={`Title of task ${number}`}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing || event.keyCode === 229) return;
              if (event.key === "Enter" && draft.trim()) {
                onRename(draft.trim());
                setEditing(false);
              } else if (event.key === "Escape") {
                setDraft(task.title);
                setEditing(false);
              }
            }}
            onBlur={() => {
              setDraft(task.title);
              setEditing(false);
            }}
          />
        ) : (
          <span className="flex items-start gap-1">
            <span className="min-w-0 flex-1 px-1 py-0.5 text-sm font-medium">
              {all.slice(0, words).map((word, index) => (
                <motion.span
                  key={`${word}-${index}`}
                  initial={reduceMotion ? false : { opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.25 }}
                >
                  {word}{" "}
                </motion.span>
              ))}
            </span>
            {complete && !locked ? (
              <Button
                variant="ghost"
                size="icon"
                className="size-7 shrink-0"
                onClick={() => {
                  setDraft(task.title);
                  setEditing(true);
                }}
                aria-label={`Edit task ${number}, ${task.title}`}
              >
                <PencilIcon />
              </Button>
            ) : null}
          </span>
        )}
        {complete ? (
          <motion.div
            initial={reduceMotion ? false : { opacity: 0 }}
            animate={{ opacity: 1 }}
            className="flex flex-wrap items-center gap-x-3 gap-y-1 px-1 text-xs text-muted-foreground"
          >
            {afterNumber !== null ? (
              <span className={cn("flex items-center gap-1", afterNumber > number && STATUS_TEXT.watch)}>
                <DependsIcon aria-hidden="true" className="size-3.5" />
                After {afterNumber}
                {afterNumber > number ? ", which now comes later" : ""}
              </span>
            ) : null}
            <span className="tabular-nums">
              {task.days} {task.days === 1 ? "day" : "days"}
            </span>
            <span className="flex items-center gap-1.5">
              <PersonAvatar person={owner} />
              {owner.name.split(" ")[0]}
            </span>
            {send ? (
              <span className={cn("flex items-center gap-1", send.startsWith("FH") && STATUS_TEXT.good)}>
                {send.startsWith("FH") ? <CircleCheckIcon aria-hidden="true" className="size-3.5" /> : null}
                {send === "queued" ? "Waiting" : send === "sending" ? "Creating issue" : `Created ${send}`}
              </span>
            ) : null}
          </motion.div>
        ) : null}
      </div>
      {complete && !locked ? (
        <Button variant="ghost" size="icon" className="size-7 shrink-0" onClick={onRedraft} aria-label={`Draft task ${number} again`}>
          <RefreshIcon />
        </Button>
      ) : null}
    </Reorder.Item>
  );
}

import { cn } from "@/lib/utils";

import { HUE_BORDER, HUE_FILL, type Person } from "./people";

/** Props for one person's initials badge. */
export interface PersonAvatarProps {
  person: Person;
  /** `sm` is 1.5rem, `md` is 2rem. */
  size?: "sm" | "md";
  /** Shows the name to screen readers. Leave it off when the name is already written beside the badge. */
  labelled?: boolean;
  className?: string;
}

/**
 * A round badge with a person's initials, ringed and tinted in their hue. The
 * tint is a faded layer behind the letters, so the letters keep full contrast.
 */
export function PersonAvatar({ person, size = "sm", labelled = false, className }: PersonAvatarProps) {
  return (
    <span
      role={labelled ? "img" : undefined}
      aria-label={labelled ? person.name : undefined}
      aria-hidden={labelled ? undefined : true}
      title={person.name}
      className={cn(
        "relative isolate inline-grid shrink-0 place-items-center overflow-hidden rounded-full border-2 bg-card font-semibold text-foreground",
        HUE_BORDER[person.hue],
        size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
        className,
      )}
    >
      <span aria-hidden="true" className={cn("absolute inset-0 -z-10 opacity-25", HUE_FILL[person.hue])} />
      {person.initials}
    </span>
  );
}

/** Props for a row of overlapping initials badges. */
export interface AvatarStackProps {
  people: Person[];
  /** Badges past this count fold into a "+N" badge. */
  max?: number;
  size?: "sm" | "md";
  className?: string;
}

/** A row of overlapping initials badges, named as one group, such as the people on a project. */
export function AvatarStack({ people, max = 4, size = "sm", className }: AvatarStackProps) {
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <span
      role="img"
      aria-label={people.map((member) => member.name).join(", ")}
      className={cn("flex items-center -space-x-1.5", className)}
    >
      {shown.map((member) => (
        <PersonAvatar key={member.id} person={member} size={size} className="ring-2 ring-card" />
      ))}
      {rest > 0 ? (
        <span
          aria-hidden="true"
          className={cn(
            "inline-grid shrink-0 place-items-center rounded-full border-2 border-border bg-card font-medium text-muted-foreground ring-2 ring-card",
            size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
          )}
        >
          +{rest}
        </span>
      ) : null}
    </span>
  );
}

/** The five chart hues, in order. A person or a calendar takes one by index. */
export type Hue = 1 | 2 | 3 | 4 | 5;

/** One member of the Fernhill team, used across the project blocks. */
export interface Person {
  id: string;
  name: string;
  initials: string;
  hue: Hue;
}

/** The Fernhill team. Every block draws its owners, attendees and authors from this list. */
export const TEAM: Person[] = [
  { id: "ines", name: "Ines Varga", initials: "IV", hue: 1 },
  { id: "tomas", name: "Tomas Reyes", initials: "TR", hue: 2 },
  { id: "noor", name: "Noor Haddad", initials: "NH", hue: 3 },
  { id: "kofi", name: "Kofi Mensah", initials: "KM", hue: 4 },
  { id: "lena", name: "Lena Brandt", initials: "LB", hue: 5 },
  { id: "arjun", name: "Arjun Patel", initials: "AP", hue: 2 },
];

/** The person with this id. Unknown ids fall back to the first person, so sample data never renders blank. */
export function person(id: string): Person {
  return TEAM.find((member) => member.id === id) ?? TEAM[0]!;
}

/** A solid fill in each hue, for a bar, a dot or a marker. Written out so the class lint can read every name. */
export const HUE_FILL = {
  1: "bg-chart-1",
  2: "bg-chart-2",
  3: "bg-chart-3",
  4: "bg-chart-4",
  5: "bg-chart-5",
} satisfies Record<Hue, string>;

/** A border in each hue. */
export const HUE_BORDER = {
  1: "border-chart-1",
  2: "border-chart-2",
  3: "border-chart-3",
  4: "border-chart-4",
  5: "border-chart-5",
} satisfies Record<Hue, string>;

/** Text in each hue, for an icon or a small mark. Not for body text: a hue may not reach 4.5 to 1. */
export const HUE_TEXT = {
  1: "text-chart-1",
  2: "text-chart-2",
  3: "text-chart-3",
  4: "text-chart-4",
  5: "text-chart-5",
} satisfies Record<Hue, string>;
